DROP TABLE IF EXISTS `planificaciones_semanales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `planificaciones_semanales` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_temporada` int NOT NULL,
  `nro_semana` int NOT NULL,
  `dia_semana` int NOT NULL,
  `fecha` date NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_temporada_fecha` (`id_temporada`,`fecha`),
  KEY `idx_planificaciones_fecha` (`fecha`),
  CONSTRAINT `fk_planificaciones_temporadas` FOREIGN KEY (`id_temporada`) REFERENCES `temporadas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `planificaciones_semanales_chk_1` CHECK ((`dia_semana` between 1 and 7))
) ENGINE=InnoDB AUTO_INCREMENT=348 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

